{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C87", "C107", "C125", "C130", "C147", "C151"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C87", "C107", "C125", "C147"],
  "claims": [
    {
      "claim": "Cicaprost, a prostacyclin analog with an ether-acetic acid side chain, showed 100% absolute oral bioavailability from matched oral and IV AUCs, the closest direct F evidence for the query class.",
      "card_ids": ["C87"]
    },
    {
      "claim": "Dinoprost, a prostaglandin acid, showed high rat jejunal effective permeability of 1.46 to 2.57 x 10^-4 cm/s at pH 4.5 and 3.5, showing that ionized prostaglandin acids can be well absorbed.",
      "card_ids": ["C107", "C125"]
    },
    {
      "claim": "PGE2 showed measurable Caco-2 permeability of 5.0 x 10^-7 cm/s at 37 C and PGF2alpha was stable in intestinal lumen with under 20% degradation in 30 min, supporting absorption of this acid class.",
      "card_ids": ["C147", "C151"]
    },
    {
      "claim": "Dinoprost free acid water solubility of 1.5 mg/mL indicates adequate dissolution for the prostaglandin acid class, addressing the solubility component.",
      "card_ids": ["C130"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C107", "C125", "C130", "C147", "C151"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No matched oral-versus-IV study for the query.",
    "L4 permeability records are for PGF2alpha and PGE2, not the exact benzindene prostacyclin core of the query.",
    "Carrier-mediated absorption is not directly demonstrated for the query.",
    "Formulation and dose effects are unknown."
  ],
  "decision_summary": "L4 adds prostaglandin-class absorption evidence: dinoprost showed high rat jejunal effective permeability of 1.46 to 2.57 x 10^-4 cm/s, PGE2 showed measurable Caco-2 permeability, PGF2alpha was stable in intestinal lumen, and dinoprost free acid solubility was 1.5 mg/mL. This directly counters the prior passive-permeability concern for ionized prostaglandin acids and supports the L3 cicaprost 100% F evidence. The high prediction is strengthened with moderate confidence."
}

